  `shop_id` bigint unsigned NOT NULL COMMENT '店铺id',
  `user_id` bigint unsigned NOT NULL COMMENT '用户id',
  `overall_score` int NOT NULL COMMENT '综合评分，按10倍存储',
  `taste_score` int DEFAULT NULL COMMENT '口味评分',
  `environment_score` int DEFAULT NULL COMMENT '环境评分',
  `service_score` int DEFAULT NULL COMMENT '服务评分',
  `content` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '评价内容',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '标签，逗号分隔',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
