--
-- Table structure for table `tb_voucher_reconcile_log`
--

DROP TABLE IF EXISTS `tb_voucher_reconcile_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_voucher_reconcile_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `voucher_id` bigint NOT NULL COMMENT '券ID',
  `message_id` varchar(64) DEFAULT NULL COMMENT '消息ID',
  `detail` varchar(1024) DEFAULT NULL COMMENT '扩展说明',
  `before_qty` int DEFAULT NULL COMMENT '变更前库存',
  `change_qty` int NOT NULL DEFAULT '0' COMMENT '变化量',
  `after_qty` int DEFAULT NULL COMMENT '变更后库存',
  `trace_id` varchar(64) NOT NULL COMMENT 'Redis trace ID',
  `log_type` varchar(32) NOT NULL COMMENT '日志类型',
  `business_type` varchar(32) NOT NULL COMMENT '业务类型',
  `reconciliation_status` varchar(32) NOT NULL COMMENT '对账状态',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_order_id` (`order_id`) USING BTREE,
  KEY `idx_trace_id` (`trace_id`) USING BTREE,
  KEY `idx_voucher_log_type` (`voucher_id`,`log_type`) USING BTREE,
  KEY `idx_reconciliation_status` (`reconciliation_status`) USING BTREE,
  KEY `idx_log_type_create_time` (`log_type`,`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=186048 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

